(-70px,-40px) scale(1.2)}}\n@keyframes slAurora3{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(50px,-50px) scale(1.1)}}\n@keyframes slRingDraw{from{stroke-dashoffset:339}}\n@keyframes slBar{from{width:0}}\n@keyframes slChipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}\n@keyframes slTick{0%{opacity:0;transform:translateY(6px)}10%,90%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-6px)}}\n@keyframes slBeam{0%{opacity:.5}50%{opacity:1}100%{opacity:.5}}\n.sl-reveal{opacity:0;transform:translateY(36px);transition:opacity .8s cubic-bezier(.22,1,.36,1),transform .8s cubic-bezier(.22,1,.36,1)}\n.sl-reveal.in{opacity:1;transform:none}\n.sl-reveal.sl-scale{transform:scale(.88)}\n.sl-reveal.sl-scale.in{transform:none}\n.sl-reveal.sl-left{transform:translateX(-44px)}\n.sl-reveal.sl-right{transform:translateX(44px)}\n.sl-reveal.sl-left.in,.sl-reveal.sl-right.in{transform:none}\n.sl-anim-grad{background-size:200% auto;animation:slGrad 4s linear infinite}\n.sl-pop-featured{animation:slPulseGlow 3s ease-in-out infinite}\n.sl-heroglow{animation:slFloat2 10s ease-in-out infinite}\n.sl-feat:hover .sl-featicon{transform:rotate(-8deg) scale(1.08)}\n.sl-featicon{transition:transform .3s cubic-bezier(.34,1.56,.64,1)}\n.sl-shimmerwrap{position:relative;overflow:hidden}\n.sl-shimmerwrap::after{content:\"\";position:absolute;top:0;left:0;width:40%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.25),transparent);transform:translateX(-120%);animation:slShimmer 4.5s ease-in-out infinite}\n.sl-stagger > .sl-reveal:nth-child(1){transition-delay:.05s}\n.sl-stagger > .sl-reveal:nth-child(2){transition-delay:.13s}\n.sl-stagger > .sl-reveal:nth-child(3){transition-delay:.21s}\n.sl-stagger > .sl-reveal:nth-child(4){transition-delay:.29s}\n.sl-stagger > .sl-reveal:nth-child(5){transition-delay:.37s}\n.sl-stagger > .sl-reveal:nth-child(6){transition-delay:.45s}\n.sl-stagger > .sl-reveal:nth-child(7){transition-delay:.5s}\n.sl-stagger > .sl-reveal:nth-child(n+8){transition-delay:.55s}\n.sl-rise{opacity:0;animation:slUp .7s cubic-bezier(.22,1,.36,1) forwards}\n.sl-pop{opacity:0;animation:slZoom .6s cubic-bezier(.22,1,.36,1) forwards}\n.sl-feat:hover,.sl-plan:hover{transform:translateY(-6px)}\n.sl-feat,.sl-plan{transition:transform .25s ease,box-shadow .25s ease}\n.sl-btn{transition:transform .2s ease,box-shadow .2s ease}\n.sl-btn:hover{transform:translateY(-2px)}\n@keyframes slFlow{0%{background-position:0% 0}100%{background-position:200% 0}}\n@keyframes slGlowPulse{0%,100%{opacity:.5;transform:scale(1)}50%{opacity:.9;transform:scale(1.015)}}\n@keyframes slFloatY{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}\n.sl-app{transition:transform .28s cubic-bezier(.22,1,.36,1),box-shadow .28s ease,border-color .28s ease}\n.sl-app:hover{transform:translateY(-6px);box-shadow:0 20px 44px -14px rgba(143,57,172,.28);border-color:rgba(143,57,172,.4)}\n.sl-app:hover .sl-appicon{animation:slFloatY 1.6s ease-in-out infinite}\n.sl-faq{transition:border-color .25s ease,box-shadow .25s ease,background .25s ease}\n.sl-faq:hover{border-color:rgba(143,57,172,.4)}\n.sl-faq-body{overflow:hidden;transition:max-height .4s cubic-bezier(.22,1,.36,1),opacity .3s ease,margin-top .3s ease}\n.sl-faq-chev{transition:transform .3s cubic-bezier(.22,1,.36,1)}\n.sl-pop-ring{position:absolute;inset:-2px;border-radius:20px;background:linear-gradient(135deg,#8F39AC,#379FD3);filter:blur(10px);opacity:.5;z-index:0;animation:slGlowPulse 3s ease-in-out infinite}\n@keyframes slBorderGlow{0%,100%{box-shadow:0 20px 48px -12px rgba(143,57,172,.3)}50%{box-shadow:0 22px 60px -8px rgba(143,57,172,.55)}}\n@keyframes slSpin{to{transform:rotate(360deg)}}\n.sl-planwrap{position:relative;border-radius:18px;height:100%}\n.sl-beam{padding:2.5px;overflow:hidden;box-shadow:0 22px 56px -12px rgba(143,57,172,.5)}\n.sl-beam::before{content:\"\";position:absolute;inset:-60%;background:conic-gradient(from 0deg,transparent 0deg 232deg,#8F39AC 288deg,#C77DFF 324deg,#5BC5F2 350deg,transparent 360deg);animation:slSpin 4s linear infinite;z-index:0}\n.sl-beam>.sl-plan{position:relative;z-index:1;height:100%}\n.sl-plan{position:relative;overflow:hidden;transition:transform .28s cubic-bezier(.22,1,.36,1),box-shadow .28s ease}\n.sl-planwrap:not(.sl-beam) .sl-plan:hover{transform:translateY(-8px)}\n.sl-plan::after{content:\"\";position:absolute;top:0;left:-130%;width:55%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.4),transparent);transform:skewX(-18deg);transition:left .75s cubic-bezier(.22,1,.36,1);pointer-events:none;z-index:2}\n.sl-planwrap:hover .sl-plan::after{left:170%}\n@keyframes slScanY{0%{top:8%;opacity:0}20%{opacity:1}80%{opacity:1}100%{top:92%;opacity:0}}\n@keyframes slBubble{from{opacity:0;transform:translateY(10px) scale(.97)}to{opacity:1;transform:none}}\n@keyframes slPinPulse{0%,100%{box-shadow:0 0 0 0 rgba(143,57,172,.5)}70%{box-shadow:0 0 0 10px rgba(143,57,172,0)}}\n.sl-pin{transition:transform .25s ease}\n.sl-pin:hover{transform:translateY(-4px)}\n.sl-pin:hover .sl-pindot{animation:slPinPulse 1.4s ease-out infinite}\n.sl-chip-q{transition:all .2s ease;cursor:pointer}\n.sl-chip-q:hover{border-color:var(--fy-purple,#8F39AC) !important;color:#8F39AC !important}\n.sl-grad-txt{background:linear-gradient(135deg,#C77DFF,#5BC5F2);-webkit-background-clip:text;background-clip:text;color:transparent}\n@keyframes slDraw{from{stroke-dashoffset:260}to{stroke-dashoffset:0}}\n@keyframes slPulseBar{0%,100%{opacity:1}50%{opacity:.55}}\n.sl-bento{transition:transform .28s cubic-bezier(.22,1,.36,1),box-shadow .28s ease}\n.sl-bento:hover{transform:translateY(-6px);box-shadow:0 22px 48px -14px rgba(143,57,172,.32)}\n.sl-bento:hover .sl-arrow{transform:translateX(5px);opacity:1}\n.sl-arrow{transition:transform .25s ease,opacity .25s ease;opacity:.5}\n.sl-mod{transition:all .2s ease;cursor:default}\n.sl-mod:hover{background:linear-gradient(135deg,#8F39AC,#379FD3) !important;color:#fff !important;border-color:transparent !important;transform:translateY(-2px);box-shadow:0 8px 18px rgba(143,57,172,.3)}\n.sl-mod:hover .dashicons{color:#fff !important}\n.sl-uline{height:4px;width:64px;margin:16px auto 0;border-radius:999px;background:linear-gradient(90deg,#8F39AC,#379FD3)}\n@media(max-width:860px){.sl-herogrid{grid-template-columns:1fr !important;gap:52px !important}}\n.sl-hdr{transition:background .3s ease,backdrop-filter .3s ease,box-shadow .3s ease,height .3s ease;background:transparent}\n.sl-hdr.scrolled{background:rgba(18,11,26,.82);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);box-shadow:0 10px 30px -14px rgba(0,0,0,.6);height:64px}\n@media(max-width:820px){.sl-bentotop{grid-template-columns:1fr !important}.sl-bentorow{grid-template-columns:1fr !important}.sl-bento-a{grid-column:auto !important;grid-row:auto !important}.sl-appgrid{grid-template-columns:1fr !important}.sl-faqgrid{grid-template-columns:1fr !important}}\n@media(max-width:780px){.sl-nav{display:none !important}.sl-navlogin{display:none !important}}\n@media(min-width:781px){.sl-navspace{display:none !important}}\n<\u002Fstyle>\n<\u002Fhelmet>\n<div class=\"sl\" style=\"background:var(--card)\">\n\n  <!-- NAV -->\n  <header class=\"sl-hdr\" id=\"sl-hdr\" style=\"position:fixed;top:0;left:0;right:0;z-index:30;display:flex;align-items:center;gap:20px;height:72px;padding:0 clamp(18px,4vw,48px)\">\n    <div style=\"display:flex;align-items:center;gap:11px\"><img src=\"977ad026-b5c1-415c-aa50-5062b62f568d\" alt=\"Fyndable\" style=\"height:46px\"><span style=\"display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);font-size:10.5px;font-weight:700;color:rgba(255,255,255,.75)\"><span style=\"width:5px;height:5px;border-radius:50%;background:#28c840\"><\u002Fspan>Shopify Partner<\u002Fspan><\u002Fdiv>\n    <nav class=\"sl-nav\" style=\"flex:1;display:flex;justify-content:center;gap:30px\">\n      <sc-for list=\"{{navLinks}}\" as=\"n\" hint-placeholder-count=\"4\"><a href=\"{{n.href}}\" style=\"font-size:14px;font-weight:600;color:rgba(255,255,255,.75)\" style-hover=\"color:#fff\">{{n.label}}<\u002Fa><\u002Fsc-for>\n    <\u002Fnav>\n    <div class=\"sl-navspace\" style=\"flex:1\"><\u002Fdiv>\n    <a href=\"#pricing\" class=\"sl-btn\" style=\"display:inline-flex;align-items:center;gap:8px;height:42px;padding:0 22px;border-radius:999px;background:linear-gradient(135deg,#8F39AC,#379FD3);color:#fff;font-size:13.5px;font-weight:600;box-shadow:0 6px 18px rgba(143,57,172,.45)\"><span class=\"dashicons dashicons-cart\" style=\"font-size:15px;width:15px;height:15px\"><\u002Fspan>Start gratis proef<\u002Fa>\n  <\u002Fheader>\n\n  <!-- HERO -->\n  <section style=\"background:linear-gradient(135deg,#2A1533,#132A38);padding:84px clamp(18px,4vw,48px) 80px;position:relative;overflow:hidden\">\n    <div style=\"position:absolute;top:-10%;right:8%;width:520px;height:520px;border-radius:50%;filter:blur(70px);background:radial-gradient(circle,rgba(143,57,172,.55),transparent 65%);animation:slAurora1 16s ease-in-out infinite\"><\u002Fdiv>\n    <div style=\"position:absolute;bottom:-20%;left:-6%;width:480px;height:480px;border-radius:50%;filter:blur(72px);background:radial-gradient(circle,rgba(55,159,211,.42),transparent 65%);animation:slAurora2 19s ease-in-out infinite\"><\u002Fdiv>\n    <div style=\"position:absolute;top:30%;left:38%;width:360px;height:360px;border-radius:50%;filter:blur(80px);background:radial-gradient(circle,rgba(199,125,255,.3),transparent 65%);animation:slAurora3 22s ease-in-out infinite\"><\u002Fdiv>\n    <div style=\"position:absolute;inset:0;opacity:.3;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:46px 46px;mask-image:radial-gradient(ellipse 80% 70% at 50% 40%,#000,transparent)\"><\u002Fdiv>\n\n    <div class=\