u002Fa>\n        <\u002Fdiv>\n        <div class=\"sl-rise\" style=\"animation-delay:.42s;display:flex;gap:20px;flex-wrap:wrap;max-width:560px;margin:46px 0 0;padding-top:28px;border-top:1px solid rgba(255,255,255,.15)\">\n          <div style=\"flex:1;min-width:110px\"><div id=\"sl-st0\" style=\"font-size:clamp(26px,3.4vw,36px);font-weight:700;color:#fff;line-height:1\">2 min<\u002Fdiv><div style=\"font-size:12.5px;color:rgba(255,255,255,.6);margin-top:6px\">Tot volledig live<\u002Fdiv><\u002Fdiv>\n          <div style=\"flex:1;min-width:110px\"><div id=\"sl-st1\" style=\"font-size:clamp(26px,3.4vw,36px);font-weight:700;color:#fff;line-height:1\">98%<\u002Fdiv><div style=\"font-size:12.5px;color:rgba(255,255,255,.6);margin-top:6px\">Tevredenheid<\u002Fdiv><\u002Fdiv>\n          <div style=\"flex:1;min-width:110px\"><div id=\"sl-st2\" style=\"font-size:clamp(26px,3.4vw,36px);font-weight:700;color:#fff;line-height:1\">14<\u002Fdiv><div style=\"font-size:12.5px;color:rgba(255,255,255,.6);margin-top:6px\">SEO-modules<\u002Fdiv><\u002Fdiv>\n          <div style=\"flex:1;min-width:110px\"><div id=\"sl-st3\" style=\"font-size:clamp(26px,3.4vw,36px);font-weight:700;color:#fff;line-height:1\">3×<\u002Fdiv><div style=\"font-size:12.5px;color:rgba(255,255,255,.6);margin-top:6px\">Meer organisch verkeer<\u002Fdiv><\u002Fdiv>\n        <\u002Fdiv>\n      <\u002Fdiv>\n\n      <!-- LIVE PRODUCT MOCKUP -->\n      <div class=\"sl-rise sl-heroglow\" style=\"animation-delay:.34s;position:relative\">\n        <div style=\"position:absolute;-webkit-box-reflect:unset;inset:-2px;border-radius:22px;background:linear-gradient(135deg,rgba(143,57,172,.6),rgba(55,159,211,.6));filter:blur(22px);opacity:.6\"><\u002Fdiv>\n        <div style=\"position:relative;background:rgba(255,255,255,.98);border-radius:20px;box-shadow:0 30px 70px -20px rgba(0,0,0,.5);overflow:hidden;border:1px solid rgba(255,255,255,.4)\">\n          <div style=\"display:flex;align-items:center;gap:8px;padding:13px 16px;backg