#fff\">{{active.title}}<\u002Fdiv><div style=\"font-size:12.5px;color:rgba(255,255,255,.6)\">{{active.sub}}<\u002Fdiv><\u002Fdiv>\n              <span style=\"display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:#28c840;padding:5px 11px;border-radius:999px;background:rgba(40,200,64,.14)\"><span style=\"width:6px;height:6px;border-radius:50%;background:#28c840;animation:slBeam 1.6s infinite\"><\u002Fspan>Live<\u002Fspan>\n            <\u002Fdiv>\n            <div style=\"background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:18px 20px;margin-bottom:18px\">\n              <sc-if value=\"{{active.vBars}}\" hint-placeholder-val=\"{{true}}\">\n              <div>\n                <sc-for list=\"{{active.bars}}\" as=\"b\" hint-placeholder-count=\"3\">\n                  <div style=\"margin-bottom:13px\"><div style=\"display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:6px\"><span style=\"color:rgba(255,255,255,.82);font-weight:600\">{{b.label}}<\u002Fspan><span style=\"color:#C77DFF;font-weight:700\">{{b.val}}<\u002Fspan><\u002Fdiv><div style=\"height:8px;border-radius:999px;background:rgba(255,255,255,.1);overflow:hidden\"><div style=\"height:100%;width:{{b.pct}};border-radius:999px;background:linear-gradient(90deg,#8F39AC,#379FD3);transition:width .55s cubic-bezier(.22,1,.36,1)\"><\u002Fdiv><\u002Fdiv><\u002Fdiv>\n                <\u002Fsc-for>\n                <div style=\"display:flex;align-items:flex-end;justify-content:space-between;margin-top:16px;padding-top:14px;border-top:1px solid rgba(255,255,255,.1)\">\n                  <div><div style=\"font-size:11px;color:rgba(255,255,255,.55);text-transform:uppercase;letter-spacing:.05em;margin-bottom:3px\">{{active.statLabel}}<\u002Fdiv><div style=\"font-size:22px;font-weight:700;color:#fff;line-height:1\">{{active.statVal}}<\u002Fdiv><\u002Fdiv>\n                  <svg sc-camel-view-box=\"0 0 160 52\" style=\"width:160px;heig