.vTech}}\" hint-placeholder-val=\"\">\n              <div>\n                <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:10px\"><span style=\"font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:rgba(255,255,255,.6)\">Schema markup · Product<\u002Fspan><span style=\"display:inline-flex;align-items:center;gap:5px;font-size:10.5px;font-weight:700;color:#28c840;padding:3px 9px;border-radius:999px;background:rgba(40,200,64,.14)\"><span class=\"dashicons dashicons-yes-alt\" style=\"font-size:12px;width:12px;height:12px\"><\u002Fspan>Geldig · Rich result<\u002Fspan><\u002Fdiv>\n                <div style=\"background:rgba(0,0,0,.3);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:14px 16px;font-family:ui-monospace,Menlo,monospace;font-size:12px;line-height:1.7\">\n                  <sc-for list=\"{{active.schema}}\" as=\"l\" hint-placeholder-count=\"7\">\n                    <div style=\"white-space:pre;color:rgba(255,255,255,.5)\">{{l.pad}}<span style=\"color:#5BC5F2\">{{l.key}}<\u002Fspan>{{l.sep}}<span style=\"color:#C77DFF\">{{l.val}}<\u002Fspan><\u002Fdiv>\n                  <\u002Fsc-for>\n                <\u002Fdiv>\n              <\u002Fdiv>\n              <\u002Fsc-if>\n\n              <sc-if value=\"{{active.vBlog}}\" hint-placeholder-val=\"\">\n              <div>\n                <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:12px\"><span style=\"font-size:13px;font-weight:700;color:#fff\">{{active.calLabel}}<\u002Fspan><span style=\"font-size:11px;color:rgba(255,255,255,.6)\">{{active.calNote}}<\u002Fspan><\u002Fdiv>\n                <div style=\"display:grid;grid-template-columns:repeat(7,1fr);gap:4px\">\n                  <sc-for list=\"{{active.calDows}}\" as=\"d\" hint-placeholder-count=\"7\"><div style=\"text-align:center;font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:rgba(255,255,255,.4